module.cert_revocation.fix_snippet:
# nginx
ssl_stapling on;
ssl_stapling_verify on;
ssl_trusted_certificate /etc/ssl/example.com/chain.pem;
resolver 203.0.113.53 valid=300s;

# Apache
SSLUseStapling on
SSLStaplingCache "shmcb:/var/run/ocsp(128000)"

# IIS (PowerShell)
New-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\SCHANNEL" -Name "EnableOcspStaplingForSni" -Value 1 -PropertyType DWord -Force
